#include "stdafx.h"#include <MemoryServiceH5xx.h>#include <rsuErr.h>KMemoryServiceH5xx::KMemoryServiceH5xx(): m_pMemAllocator( NULL ), m_pObjectsStructAllocator( NULL ), m_pIOsStructAllocator( NULL ), m_pRefIoCreator( NULL ), m_pOnObjectStructCreatedCallback( NULL ), m_pObjectsStructFinder( NULL ){}KMemoryServiceH5xx& KMemoryServiceH5xx::Instance(){  static KMemoryServiceH5xx _Instance;  return _Instance;}void KMemoryServiceH5xx::InitMemAllocator( tMemAllocatorImpl pfn ){  if( m_pMemAllocator )  {    ASS( m_pMemAllocator==pfn );  }  m_pMemAllocator = pfn;}void KMemoryServiceH5xx::InitObjectsStructAllocator( tStructAllocatorImpl pfn, tOnObjectStructCreated pfnCallback, tStructFinder pFinder ){  if( m_pObjectsStructAllocator )  {    ASS( m_pObjectsStructAllocator==pfn );  }  if( pfnCallback && m_pOnObjectStructCreatedCallback )  {    ASS( m_pOnObjectStructCreatedCallback==pfnCallback );  }  m_pObjectsStructAllocator = pfn;  m_pOnObjectStructCreatedCallback = pfnCallback;  m_pObjectsStructFinder = pFinder;}void KMemoryServiceH5xx::InitIOsStructAllocator( tStructAllocatorImpl pfn, tIoCreateRefToData pfnRef ){  if( m_pIOsStructAllocator )  {    ASS( m_pIOsStructAllocator==pfn );  }  m_pIOsStructAllocator = pfn;  if( m_pRefIoCreator )  {    ASS( m_pRefIoCreator==pfnRef );  }  m_pRefIoCreator = pfnRef;}void* KMemoryServiceH5xx::NewMem( size_t size ){  ASSD( m_pMemAllocator );  if( !m_pMemAllocator )  {    BYTE *p = new BYTE[size];    ZeroMemory( p, size );    return p;  }  return m_pMemAllocator( size );}CBase* KMemoryServiceH5xx::CreateObjectsStruct( LPCSTR ObjName, DWORD TypeID, int number ){  ASS( m_pObjectsStructAllocator );  if( !m_pObjectsStructAllocator )    return NULL;  CBase *pName = m_pObjectsStructAllocator( ObjName, TypeID, number );  if( m_pOnObjectStructCreatedCallback )  {    CBase *pAdd = m_pOnObjectStructCreatedCallback( ObjName, TypeID, number );  }    return pName;}CBase* KMemoryServiceH5xx::CreateIOsStruct( LPCSTR ObjName, DWORD TypeID, int number ){  ASS( m_pIOsStructAllocator );  if( !m_pIOsStructAllocator )    return NULL;  CBase *pName = m_pIOsStructAllocator( ObjName, TypeID, number );  return pName;}CBase* KMemoryServiceH5xx::FindObjectsStruct( LPCSTR ObjName, DWORD TypeID, int number ){  ASS( m_pObjectsStructFinder );  if( !m_pObjectsStructFinder )    return NULL;  CBase *pF = m_pObjectsStructFinder( ObjName, TypeID, number );  return pF;}int KMemoryServiceH5xx::CreateIoRefToData( LPCSTR ObjName, CBase *pBase, DWORD TypeID ){  ASS( m_pRefIoCreator );  if( !m_pRefIoCreator )    return -1;  return m_pRefIoCreator(ObjName, pBase, TypeID );}